syntax = "proto3";

package orders;

service OrderService {
  rpc GetOrder(GetOrderRequest) returns (Order);
  rpc StreamOrders(StreamRequest) returns (stream Order);
}

message Order {
  string id = 1;
  string customer_id = 2;
  repeated LineItem items = 3;
  double total = 4;
  OrderStatus status = 5;
}

enum OrderStatus { PENDING = 0; PAID = 1; SHIPPED = 2; }

// C# gRPC client with channel pooling
var channel = GrpcChannel.ForAddress("https://orders.internal");
var client = new OrderService.OrderServiceClient(channel);

var order = await client.GetOrderAsync(
    new GetOrderRequest { OrderId = "123" },
    deadline: DateTime.UtcNow.AddMilliseconds(200));

